using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";
var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing 2026";

Console.WriteLine($"🔬 Research Agent Starting...");
Console.WriteLine($"📋 Topic: {topic}\n");

// --- Tool Implementations ---
var notebook = new Notebook();

// Build the chat client with tool support
IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(
            (string query) => WebSearch.SearchAsync(query),
            "web_search",
            "Searches the web for information. Returns a list of relevant snippets and URLs."),
        AIFunctionFactory.Create(
            ([Description("A concise note to save")] string note) => notebook.AddNote(note),
            "take_note",
            "Saves a note to the research notebook for later reference when writing the summary."),
        AIFunctionFactory.Create(
            () => notebook.GetNotes(),
            "read_notes",
            "Reads all notes currently saved in the research notebook.")
    ]
};

// --- Agent Loop ---
List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research agent. Your goal is to thoroughly research the given topic
        by searching the web multiple times with different queries, taking notes on key findings,
        and then producing a well-organized summary.

        Follow this process:
        1. Break the topic into 2-3 search queries that cover different angles.
        2. For each query, search the web and take notes on the most important findings.
        3. After gathering enough information, read your notes and write a final summary.

        When you have finished your research, write your final summary directly in your response.
        Make the summary informative, well-structured, and cite sources where possible.
        """),
    new(ChatRole.User, $"Please research this topic: {topic}")
];

Console.WriteLine("🌐 Agent is researching...\n");

var response = await client.GetChatCompletionAsync(messages, chatOptions);

Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine("📝 RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════════\n");
Console.WriteLine(response.Message.Text);
Console.WriteLine("\n═══════════════════════════════════════════");
Console.WriteLine($"📓 Notes taken: {notebook.Count}");
Console.WriteLine($"🔍 Web searches performed: {WebSearch.SearchCount}");
Console.WriteLine("═══════════════════════════════════════════");

// --- Supporting Types ---

/// <summary>Simple notebook for the agent to store findings.</summary>
class Notebook
{
    private readonly List<string> _notes = [];
    public int Count => _notes.Count;

    public string AddNote(string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📓 Note saved: {note[..Math.Min(note.Length, 80)]}...");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    public string GetNotes()
    {
        if (_notes.Count == 0) return "No notes yet.";
        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

/// <summary>Web search tool using a search API (falls back to simulated results).</summary>
static class WebSearch
{
    private static int _searchCount;
    public static int SearchCount => _searchCount;

    public static async Task<string> SearchAsync(string query)
    {
        Interlocked.Increment(ref _searchCount);
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        // Try using Bing or fall back to a simulated response
        try
        {
            var searchApiKey = Environment.GetEnvironmentVariable("BING_SEARCH_API_KEY");
            if (!string.IsNullOrEmpty(searchApiKey))
            {
                return await SearchBingAsync(query, searchApiKey);
            }
        }
        catch { /* fall through to simulated results */ }

        // Simulated search results for demonstration
        return $"""
            Search results for: "{query}"

            1. [Research Article] Key developments in this area include recent breakthroughs
               and ongoing studies. Multiple institutions are contributing to progress.
               Source: https://example.com/research/{Uri.EscapeDataString(query)}

            2. [News] Recent announcements highlight significant milestones achieved in 2026,
               with new funding and collaborative projects underway.
               Source: https://example.com/news/{Uri.EscapeDataString(query)}

            3. [Academic Paper] A comprehensive review covers the state of the art,
               challenges remaining, and future directions for the field.
               Source: https://example.com/papers/{Uri.EscapeDataString(query)}
            """;
    }

    private static async Task<string> SearchBingAsync(string query, string apiKey)
    {
        using var http = new HttpClient();
        http.DefaultRequestHeaders.Add("Ocp-Apim-Subscription-Key", apiKey);
        var url = $"https://api.bing.microsoft.com/v7.0/search?q={Uri.EscapeDataString(query)}&count=5";
        var json = await http.GetStringAsync(url);
        using var doc = JsonDocument.Parse(json);
        var results = doc.RootElement.GetProperty("webPages").GetProperty("value");

        var output = new System.Text.StringBuilder();
        output.AppendLine($"Search results for: \"{query}\"\n");
        int i = 1;
        foreach (var result in results.EnumerateArray().Take(5))
        {
            var name = result.GetProperty("name").GetString();
            var snippet = result.GetProperty("snippet").GetString();
            var resultUrl = result.GetProperty("url").GetString();
            output.AppendLine($"{i}. [{name}] {snippet}\n   Source: {resultUrl}\n");
            i++;
        }
        return output.ToString();
    }
}

